  PanelText_UI_Events_2ndAnnivWB_StageGroup_Text_C_Introduction_Content = {
    Text = [[
Come! With madness, carnage, and agony as the notes, let us hymn this requiem shimmering amongst the stars!
That Blind Idiot God, the Supreme Being of Folly and Chaos, must not awaken, neither now nor in the future.]]
  },
