  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "A bird's life is destined to be a life of freedom. You should have seen it at the moment of hatching, wresting the freedom of life from the hands of death. You should have seen it when it first learned to fly, wresting the freedom of survival from the comfort of a warm nest. Now, if the Key to freedom were cast into the abyss of death, it would leap without hesitation—choosing to face the raging storm of death over a narrow life, embracing infinite freedom instead."
  },
