  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = [[
In this seaside town, there is a bustling commercial street. Maritime trade has brought countless trendy goods here; as long as you pay enough Leonian Florins, you can always find satisfactory products.
The only exception is a small shop on the corner, a quaint little place filled with magical antiques. Amid the smoke billowing from a pipe, the shopkeeper, wearing a wide-brimmed hat, will slowly reveal a smile to you.
"Welcome to the Worry-Free Shop, where all your needs can be met, as long as you offer enough compensation..."
"Of course, of course, the prices are fair, and we are honest with everyone."]]
  },
