  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = [[
She stands once again upon the Earth, and the revenge that consumes all arrives as promised.

It is an unending Pursuit, it is the searing fire of The Living Flame.

She will traverse every corner, hunting down all who have signed a Contract with Death.

Run, run, flee into the deeper Darkness, flee to a place you think will not be found.

Though it is meaningless, for He will tread through every world.

He will hunt down everything until all is reduced to ash.]]
  },
