  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = [[
One day, you suddenly realize that you've changed.
No one discovered this because you have the same behavior and demeanor, the same stunning appearance.
But you know very well that the originally bright red heart has already been covered by a mask made of mist
If I can keep pretending, am I still the same person I was before?
Congratulations, this question didn't linger in your mind for more than a second; in fact, before that mask is lifted, no one knows your true thoughts.
Then, let's set off first~]]
  },
