    Text = [[
She gazes at the great Gate at the end of the world, then steps forward without hesitation.
Click. The handle turns. Her eyes search eagerly beyond the threshold.
But there is only nothingness. She has stepped into the Illusion.
She should have known: gifts given so freely always demand the steepest price.]]
